import{_ as i,a0 as a,w as l,s as p,I as e,x as t,a1 as s,A as r,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Chromebook 如何雙啓動：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT x X-CMD","titleTemplate":false,"description":"Chromebook 如何雙啓動：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Chromebook 如何雙啓動：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Chromebook 如何雙啓動：Ubuntu 17.04 GNOME 和 Chrome OS | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170623 Chromebook Dual Boot How-to Ubuntu 17.04 GNOME and Chrome OS","title":"Chromebook 如何雙啓動：Ubuntu 17.04 GNOME 和 Chrome OS","tag":"201707","desc":""},"relativePath":"201707/20170623 Chromebook Dual Boot How-to Ubuntu 17.04 GNOME and Chrome OS.md","filePath":"[post].md"}'),h={name:"201707/20170623 Chromebook Dual Boot How-to Ubuntu 17.04 GNOME and Chrome OS.md"};function m(b,o,d,C,g,k){const n=a("Link");return l(),p("div",null,[o[19]||(o[19]=e("h1",{id:"chromebook-如何雙啓動-ubuntu-17-04-gnome-和-chrome-os",tabindex:"-1"},[t("Chromebook 如何雙啓動：Ubuntu 17.04 GNOME 和 Chrome OS "),e("a",{class:"header-anchor",href:"#chromebook-如何雙啓動-ubuntu-17-04-gnome-和-chrome-os","aria-label":"Permalink to “Chromebook 如何雙啓動：Ubuntu 17.04 GNOME 和 Chrome OS”"},"​")],-1)),o[20]||(o[20]=e("blockquote",null,[e("p",null,"本教程使用著名的 Crouton 安裝器")],-1)),o[21]||(o[21]=e("p",null,[e("img",{src:"http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-2.jpg",alt:"Ubuntu 17.04 with GNOME 3.24 running on Acer Chromebook 11 (C740)"})],-1)),e("p",null,[o[1]||(o[1]=t("在去年我拿到我的 Acer Chromebook 11 (C740) 時，我寫了一篇教程教你們如何",-1)),s(n,{href:"http://news.softpedia.com/news/here-s-how-to-install-any-linux-operating-system-on-your-chromebook-506212.shtml"},{default:r(()=>[...o[0]||(o[0]=[t("如何移除 Google Chrome OS 並根據你的選擇安裝一個 GNU/Linux 發行版",-1)])]),_:1}),o[2]||(o[2]=t("，但是很快我覺得沒意思了。",-1))]),o[22]||(o[22]=u('<p>因此幾個月之後，我使用了 Google 在網站上提供的恢復鏡像重新安裝了 Chrome OS，我寫入了 USB 並從 Chromebook 啓動。最近，我又感到無聊了，因此我決定使用 Crouton 在我的 Acer Chromebook 11 (C740) 上安裝 Ubuntu。</p><p>為什麼？因為在一次會議中來的一位朋友帶了他的筆記本，一台 Dell Chromebook 13，在上面他運行了 Ubuntu Linux 還有 Chrome OS。看他用快捷鍵在兩個操作系統之間切換很酷，這讓我也想這麼做。</p><p>現在有很多教程解釋如何安裝不同的發行版 Ubuntu、Debian 或者 Kali Linux（這些是當前 Crouton 安裝器支持的 GNU/Linux 發行版），但是我想要運行最新的 Ubuntu，當前是 Ubuntu 17.04 (Zesty Zapus)，它有 GNOME 3.24 桌面環境。</p><h3 id="如何啓用開發者模式並下載-crouton" tabindex="-1">如何啓用開發者模式並下載 Crouton <a class="header-anchor" href="#如何啓用開發者模式並下載-crouton" aria-label="Permalink to “如何啓用開發者模式並下載 Crouton”">​</a></h3><p>當我詢問我的朋友他在他的 Chromebook 上運行的是什麼 Ubuntu 時，回答是 Ubuntu 14.04 LTS (Trusty Tahr)，我不得不承認這讓我有點失望。我回家後立刻拿出我的 Chromebook 並嘗試看看我是否能運行帶有桌面環境的 Ubuntu 17.04。</p><p>我做的第一件事情是將我的 Chromebook 變成開發者模式。為此，你需要關閉你的 Chromebook 但不關閉翻蓋，接着同時按住 <code>ESC</code>、<code>Refresh</code> 和 <code>Power</code> 鍵幾秒直到進入恢復模式，這會擦除 Chromebook 上的所有數據。</p>',6)),e("p",null,[o[4]||(o[4]=t("進入開發者模式會花費你幾分鐘，所以耐心點。當準備完成後，你需要登錄你的 Google 賬户，並設置各種東西，比如壁紙或者頭像之類。現在你進入開發者模式了，在你的 Chromebook 中訪問這篇教程並",-1)),s(n,{href:"https://goo.gl/fd3zc"},{default:r(()=>[...o[3]||(o[3]=[t("下載 Crouton",-1)])]),_:1}),o[5]||(o[5]=t("，它會保存在下載文件夾中。",-1))]),o[23]||(o[23]=u(`<h3 id="如何使用-crouton-安裝帶有-gnome-3-24-的-ubuntu-17-04" tabindex="-1">如何使用 Crouton 安裝帶有 GNOME 3.24 的 Ubuntu 17.04 <a class="header-anchor" href="#如何使用-crouton-安裝帶有-gnome-3-24-的-ubuntu-17-04" aria-label="Permalink to “如何使用 Crouton 安裝帶有 GNOME 3.24 的 Ubuntu 17.04”">​</a></h3><p>現在打開 Google Chrome 並按下 <code>CTRL+ALT+T</code> 打開 Chrome OS 的終端模擬器，它叫做 crosh。在命令提示符中，輸入 <code>shell</code> 命令，按下回車進入 Linux shell。讓我們看看 Crouton 能為我們做什麼。</p><p>這有兩個命令（下面列出的），你可以運行它們查看 Crouton 支持的 GNU/Linux 發行版和桌面環境，並且我可以告訴你這可以安裝 Debian 7 “Wheezy”、Debian 8 “Jessie”、Debian 9 “Stretch” 和 Debian Sid、Kali Linux 滾動版還有 Ubuntu 12.04 LTS、Ubuntu 14.04 LTS 和 Ubuntu 16.04 LTS 等等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh -e /Downloads/crouton -r list -  ### 會列出支持的發行版 </span></span>
<span class="line"><span>sh -e /Downloads/crouton -t list -  ### 會列出支持的桌面</span></span></code></pre></div><p>Crouton 也會列出一系列 Debian、Kali 和 Ubuntu 的舊發行版，但它們在上游被中止支持了（這些的名字後面都被標記了感嘆號），並且因為安全風險你不應該安裝它們，還有兩個尚未支持的 Ubuntu 版本，Ubuntu 16.10 和 Ubuntu 17.04。</p><p>Crouton 開發者説這些“不支持”的 Ubuntu 版本用一些方法可能也可以使用，但是我試了一下並使用下面的命令安裝了帶有 GNOME 3.24 桌面環境（沒有額外的應用）的 Ubuntu 17.04 (Zesty Zapus)。我使用 <code>-e</code> 參數來加密安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh -e /Downloads/crouton -e -r zesty -t gnome</span></span></code></pre></div><p>將所有的都下載下來並安裝在 Crouton 在你的 Chromebook 中創建的 chroot 環境中會花費一些時間，因此再説一次，請耐心。當一切完成後，你會知道，並且你能通過在 shell 中運行下面的命令啓動 Ubuntu 17.04。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo startgnome</span></span></code></pre></div><p>瞧！我在我的舊 Acer Chromebook 11 (C740) 上運行着帶有 GNOME 3.24 桌面環境的 Ubuntu 17.04 (Zesty Zapus)，這筆記本 Google 還尚未支持 Android 程序。最棒的部分是我能夠使用 <code>CTRL+ALT+Shift</code>+<code>Back</code>/<code>Forward</code> 鍵盤快捷鍵快速在 Chrome OS 和 Ubuntu 17.04 之間切換。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-3.jpg" alt="GNOME 3.24 desktop - System menu"></p><p>作為這篇筆記的結尾，我想提醒你注意，由於 Chromebook 現在始終處於開發人員模式，所以當電池電量耗盡、打開或關閉設備時，你會一直看到一個警告，顯示 “OS verification is OFF - Press SPACE to re-enable”，當你看到它時，請按 <code>CTRL+D</code>。玩得開心！</p><p><img src="http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-4.jpg" alt="GNOME 3.24 desktop - Calendar applet"></p><p><img src="http://i1-news.softpedia-static.com/images/news2/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624-5.jpg" alt="GNOME 3.24 desktop - Overview mode"></p><hr>`,15)),e("p",null,[o[7]||(o[7]=t("via: ",-1)),s(n,{href:"http://news.softpedia.com/news/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624.shtml"},{default:r(()=>[...o[6]||(o[6]=[t("http://news.softpedia.com/news/how-to-install-ubuntu-17-04-with-gnome-on-your-chromebook-alongside-chrome-os-516624.shtml",-1)])]),_:1})]),e("p",null,[o[11]||(o[11]=t("作者：",-1)),s(n,{href:"http://news.softpedia.com/editors/browse/marius-nestor"},{default:r(()=>[...o[8]||(o[8]=[t("Marius Nestor",-1)])]),_:1}),o[12]||(o[12]=t(" 譯者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:r(()=>[...o[9]||(o[9]=[t("geekpi",-1)])]),_:1}),o[13]||(o[13]=t(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:r(()=>[...o[10]||(o[10]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[16]||(o[16]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[14]||(o[14]=[t("LCTT",-1)])]),_:1}),o[17]||(o[17]=t(" 原創編譯，",-1)),s(n,{href:"https://linux.cn/"},{default:r(()=>[...o[15]||(o[15]=[t("Linux中國",-1)])]),_:1}),o[18]||(o[18]=t(" 榮譽推出",-1))])])}const O=i(h,[["render",m]]);export{T as __pageData,O as default};
